1	package payflow
2	
3	import (
4		"encoding/json"
5		"math"
6		"os"
7		"reflect"
8		"testing"
9	)
10	
11	// 本文件为“净扣款差额为零不等于逐笔全部匹配”提供回归保障。
12	//
13	// 对账报告同时承载四种互相不可替代的表达：
14	//   - results：逐条核对结论（按外部流水输入顺序）；
15	//   - missing_payments / missing_refunds：入选但流水未覆盖的账本记录；
16	//   - totals：按账户、资产的扣款/退款/净扣款合计（账本侧与流水侧各一份）；
17	//   - net_diff：逐组合的净扣款差额（流水减账本）。
18	//
19	// 以下场景中外部流水的总额与账本完全对平（net_charged_diff 为十进制 "0"），
20	// 但偏差跨记录分布：一条多记、另一条等额少记，或退款交换了各自引用的原付款
21	// 编号。报告必须逐笔保留 field_mismatch 与具体字段两侧取值，命中编号的记录
22	// 不得再进缺失列表，同时汇总如实反映“总额相等”。修复偏差后对应结果恢复
23	// matched；金额与手续费分项不同但 charged 相同也必须保留分项差异。整个过程
24	// 沿用全量入口 ReconcileFlow 与既有状态名称，且对账只读。
25	
26	// regNetZeroLedger 构造同一账户/资产下两笔等额成功付款 p1、p2（aa-1/usdc，
27	// amount=1000、fee=3、charged=1003，30bps），并分别全额退款 r1（退 p1）、
28	// r2（退 p2）。账本扣款合计 2006、退款合计 2006、净扣款 0。
29	func regNetZeroLedger(t *testing.T) (*Ledger, string) {
30		t.Helper()
31		path := newTestLedger(t, []BalanceInit{
32			{Account: "aa-1", Asset: "usdc", Balance: math.MaxInt64},
33		})
34		l := openOrFail(t, path)
35		res, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
36			{ID: "p1", Account: "aa-1", Paymaster: "pm", Asset: "usdc", Amount: i64p(1000), Nonce: 1, State: "pending"},
37			{ID: "p2", Account: "aa-1", Paymaster: "pm", Asset: "usdc", Amount: i64p(1000), Nonce: 2, State: "pending"},
38		}})
39		if err != nil {
40			t.Fatalf("submit: %v", err)
41		}
42		if got := statuses(res); got[0] != StatusSettled || got[1] != StatusSettled {
43			t.Fatalf("setup statuses=%v", got)
44		}
45		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
46			{ID: "r1", SettlementID: "p1", Reason: "cancel"},
47			{ID: "r2", SettlementID: "p2", Reason: "cancel"},
48		}})
49		if err != nil {
50			t.Fatalf("refund: %v", err)
51		}
52		for i, want := range []string{StatusRefundSuccess, StatusRefundSuccess} {
53			if rr.Results[i].Status != want {
54				t.Fatalf("setup refund %d status=%s", i, rr.Results[i].Status)
55			}
56		}
57		return l, path
58	}
59	
60	// regRow 在单侧汇总中定位 (account, asset) 行。
61	func regRow(t *testing.T, rows []ReconTotalRow, acct, asset string) ReconTotalRow {
62		t.Helper()
63		return findTotalRow(t, rows, acct, asset)
64	}
65	
66	// regDiff 在 net_diff 中定位 (account, asset) 行。
67	func regDiff(t *testing.T, rep *ReconReport, acct, asset string) ReconNetDiff {
68		t.Helper()
69		for _, d := range rep.NetDiff {
70			if d.Account == acct && d.Asset == asset {
71				return d
72			}
73		}
74		t.Fatalf("net_diff row %s/%s not found in %+v", acct, asset, rep.NetDiff)
75		return ReconNetDiff{}
76	}
77	
78	// regDiffMap 把一条结果的字段差异整理成 field -> {ledger, flow}。
79	func regDiffMap(r ReconResult) map[string][2]string {
80		out := make(map[string][2]string, len(r.Diffs))
81		for _, d := range r.Diffs {
82			out[d.Field] = [2]string{d.Ledger, d.Flow}
83		}
84		return out
85	}
86	
87	// regAssertBalancedTotals 校验该组合两侧汇总与净差额如实反映“总额相等”：
88	// 扣款合计与退款合计两侧各自相等，净扣款与净差额都是十进制字符串零。
89	func regAssertBalancedTotals(t *testing.T, rep *ReconReport, chargedTotal, refundedTotal string) {
90		t.Helper()
91		lg := regRow(t, rep.Totals.Ledger, "aa-1", "usdc")
92		fl := regRow(t, rep.Totals.Flow, "aa-1", "usdc")
93		if lg.ChargedTotal != chargedTotal || lg.RefundedTotal != refundedTotal || lg.NetCharged != "0" {
94			t.Fatalf("ledger totals=%+v want charged=%s refunded=%s net=0", lg, chargedTotal, refundedTotal)
95		}
96		if fl.ChargedTotal != chargedTotal || fl.RefundedTotal != refundedTotal || fl.NetCharged != "0" {
97			t.Fatalf("flow totals=%+v want charged=%s refunded=%s net=0", fl, chargedTotal, refundedTotal)
98		}
99		if d := regDiff(t, rep, "aa-1", "usdc"); d.LedgerNetCharged != "0" ||
100			d.FlowNetCharged != "0" || d.NetChargedDiff != "0" {
101			t.Fatalf("net_diff=%+v want all decimal zero", d)
102		}
103	}
104	
105	// TestReconcileOffsettingPaymentMismatchesNetZero 两笔不同编号的成功付款，
106	// 流水用正确编号定位，却一笔多记 20、另一笔等额少记 20：整批流水（连同两笔
107	// 正确的退款）扣款合计与账本完全相等，但两笔付款都必须是 field_mismatch，
108	// 且记录详情仍指向各自原付款。
109	func TestReconcileOffsettingPaymentMismatchesNetZero(t *testing.T) {
110		l, _ := regNetZeroLedger(t)
111	
112		// p1 多记 20（amount/charged 1000/1003 -> 1020/1023），p2 等额少记 20
113		// （-> 980/983）；r1、r2 按账本原值正确呈现。账户、资产、fee 一致。
114		// 付款与退款交错排列，验证逐条结果严格保持外部流水输入顺序。
115		entries, err := ParseReconcileRequest([]byte(`{"entries":[
116		  {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":980,"fee":3,"charged":983},
117		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
118		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1020,"fee":3,"charged":1023},
119		  {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"}
120		]}`))
121		if err != nil {
122			t.Fatalf("parse: %v", err)
123		}
124		rep, err := l.ReconcileFlow(entries)
125		if err != nil {
126			t.Fatalf("reconcile: %v", err)
127		}
128	
129		// 逐条结果保持外部流水输入顺序：两笔偏差付款是字段不符，两笔正确退款匹配。
130		wantOrder := []struct {
131			id     string
132			kind   string
133			status string
134		}{
135			{"p2", "payment", ReconFieldMismatch},
136			{"r1", "refund", ReconMatched},
137			{"p1", "payment", ReconFieldMismatch},
138			{"r2", "refund", ReconMatched},
139		}
140		if len(rep.Results) != len(wantOrder) {
141			t.Fatalf("want %d results, got %d", len(wantOrder), len(rep.Results))
142		}
143		for i, w := range wantOrder {
144			r := rep.Results[i]
145			if r.Index != i || r.ID != w.id || r.Kind != w.kind {
146				t.Fatalf("result %d not in input order: %+v want %s/%s", i, r, w.kind, w.id)
147			}
148			if r.Status != w.status {
149				t.Fatalf("result %d (%s) status=%s want %s; totals balancing must not mask per-record diffs",
150					i, r.ID, r.Status, w.status)
151			}
152		}
153	
154		// p2 少记：差异落在 amount 与 charged，逐字保留两侧取值。
155		d2 := regDiffMap(rep.Results[0])
156		if len(d2) != 2 {
157			t.Fatalf("p2 diffs=%v want exactly amount,charged", d2)
158		}
159		if d2["amount"] != [2]string{"1000", "980"} {
160			t.Fatalf("p2 amount diff=%v want ledger 1000 flow 980", d2["amount"])
161		}
162		if d2["charged"] != [2]string{"1003", "983"} {
163			t.Fatalf("p2 charged diff=%v want ledger 1003 flow 983", d2["charged"])
164		}
165		// p1 多记。
166		d1 := regDiffMap(rep.Results[2])
167		if len(d1) != 2 {
168			t.Fatalf("p1 diffs=%v want exactly amount,charged", d1)
169		}
170		if d1["amount"] != [2]string{"1000", "1020"} {
171			t.Fatalf("p1 amount diff=%v want ledger 1000 flow 1020", d1["amount"])
172		}
173		if d1["charged"] != [2]string{"1003", "1023"} {
174			t.Fatalf("p1 charged diff=%v want ledger 1003 flow 1023", d1["charged"])
175		}
176	
177		// 记录详情仍指向各自原付款（包括退款关联），不得因金额串号而互换。
178		r2 := rep.Results[0].Record
179		if r2 == nil || r2.Kind != "payment" || r2.ID != "p2" || r2.Seq != 2 ||
180			r2.Amount != 1000 || r2.Fee != 3 || r2.Charged != 1003 || r2.RefundID != "r2" {
181			t.Fatalf("p2 record must point to original payment: %+v", r2)
182		}
183		r1 := rep.Results[2].Record
184		if r1 == nil || r1.Kind != "payment" || r1.ID != "p1" || r1.Seq != 1 ||
185			r1.Amount != 1000 || r1.Fee != 3 || r1.Charged != 1003 || r1.RefundID != "r1" {
186			t.Fatalf("p1 record must point to original payment: %+v", r1)
187		}
188	
189		// 四条记录全部通过各自编号找到：缺失列表（付款与退款）必须为空，
190		// 命中编号的记录不能因为字段不符而被当成缺失。
191		if len(rep.MissingPayments) != 0 {
192			t.Fatalf("matched-by-id payments must not be missing: %+v", rep.MissingPayments)
193		}
194		if len(rep.MissingRefunds) != 0 {
195			t.Fatalf("covered refunds must not be missing: %+v", rep.MissingRefunds)
196		}
197	
198		// 扣款合计 1023+983=2006 与账本相等，净扣款、净差额如实为零。
199		regAssertBalancedTotals(t, rep, "2006", "2006")
200	
201		// 把偏差改回账本原值：四条恢复 matched，缺失列表仍为空，汇总保持相等。
202		corrected := []FlowEntry{
203			{Index: 0, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
204			{Index: 1, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
205				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
206			{Index: 2, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
207			{Index: 3, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
208				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
209		}
210		rep2, err := l.ReconcileFlow(corrected)
211		if err != nil {
212			t.Fatalf("reconcile corrected: %v", err)
213		}
214		for i, r := range rep2.Results {
215			if r.Status != ReconMatched || len(r.Diffs) != 0 {
216				t.Fatalf("corrected result %d (%s)=%+v want matched", i, r.ID, r)
217			}
218		}
219		if len(rep2.MissingPayments) != 0 || len(rep2.MissingRefunds) != 0 {
220			t.Fatalf("corrected missing=%+v/%+v", rep2.MissingPayments, rep2.MissingRefunds)
221		}
222		regAssertBalancedTotals(t, rep2, "2006", "2006")
223	}
224	
225	// TestReconcilePaymentFeeBreakdownDiffChargedEqual amount 与 fee 分项互换、
226	// charged 总额相同：净差额为零也必须保留两个分项差异，不能因总额一致而匹配。
227	func TestReconcilePaymentFeeBreakdownDiffChargedEqual(t *testing.T) {
228		l, _ := regNetZeroLedger(t)
229		// 账本 p1：amount=1000 fee=3 charged=1003；流水：amount=990 fee=13
230		// charged=1003。分项不同、扣款总额相同。只核对 p1。
231		entries := []FlowEntry{
232			{Index: 0, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc",
233				Amount: 990, Fee: 13, Charged: 1003},
234		}
235		rep, err := l.ReconcileFlow(entries)
236		if err != nil {
237			t.Fatalf("reconcile: %v", err)
238		}
239		r := rep.Results[0]
240		if r.Status != ReconFieldMismatch {
241			t.Fatalf("status=%s want field_mismatch: equal charged must not hide amount/fee diffs", r.Status)
242		}
243		d := regDiffMap(r)
244		if len(d) != 2 {
245			t.Fatalf("diffs=%v want exactly amount,fee", d)
246		}
247		if d["amount"] != [2]string{"1000", "990"} {
248			t.Fatalf("amount diff=%v", d["amount"])
249		}
250		if d["fee"] != [2]string{"3", "13"} {
251			t.Fatalf("fee diff=%v", d["fee"])
252		}
253		if _, ok := d["charged"]; ok {
254			t.Fatalf("charged must not be listed as diff: %v", d["charged"])
255		}
256		if r.Record == nil || r.Record.ID != "p1" {
257			t.Fatalf("record detail missing: %+v", r.Record)
258		}
259		// 只来一笔 1003 的扣款：流水侧 charged_total=1003，与账本侧 2006 不等，
260		// 净差额按真实总额给出（不允许因为 p1 自身 charged 相同而置零）。
261		lg := regRow(t, rep.Totals.Ledger, "aa-1", "usdc")
262		fl := regRow(t, rep.Totals.Flow, "aa-1", "usdc")
263		if lg.ChargedTotal != "2006" || fl.ChargedTotal != "1003" {
264			t.Fatalf("totals ledger=%+v flow=%+v", lg, fl)
265		}
266		if d := regDiff(t, rep, "aa-1", "usdc"); d.NetChargedDiff != "1003" {
267			t.Fatalf("net_charged_diff=%s want 1003 (flow 1003-2006 vs ledger 0)", d.NetChargedDiff)
268		}
269	}
270	
271	// TestReconcileSwappedRefundSettlementsNetZero 两笔等额付款均已全额退款；
272	// 流水的退款编号、账户、资产、金额全部正确，只交换了各自引用的原付款编号。
273	// 整批流水（连同两笔正确的原付款）退款合计与净扣款差额完全对平，两笔退款
274	// 仍必须报告 settlement_id 字段不符，并携带账本中真正的原付款关联。
275	func TestReconcileSwappedRefundSettlementsNetZero(t *testing.T) {
276		l, _ := regNetZeroLedger(t)
277	
278		// r1/r2 编号、金额均正确，仅 settlement_id 互换；p1/p2 按原扣款正确。
279		// 付款与退款交错排列，验证逐条结果严格保持外部流水输入顺序。
280		entries, err := ParseReconcileRequest([]byte(`{"entries":[
281		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"},
282		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
283		  {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
284		  {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003}
285		]}`))
286		if err != nil {
287			t.Fatalf("parse: %v", err)
288		}
289		rep, err := l.ReconcileFlow(entries)
290		if err != nil {
291			t.Fatalf("reconcile: %v", err)
292		}
293	
294		wantOrder := []struct {
295			id     string
296			kind   string
297			status string
298		}{
299			{"r1", "refund", ReconFieldMismatch},
300			{"p1", "payment", ReconMatched},
301			{"r2", "refund", ReconFieldMismatch},
302			{"p2", "payment", ReconMatched},
303		}
304		if len(rep.Results) != len(wantOrder) {
305			t.Fatalf("want %d results, got %d", len(wantOrder), len(rep.Results))
306		}
307		// 逐条结果保持输入顺序：两笔退款都是 field_mismatch，差异只在 settlement_id，
308		// 付款曾经退款不影响原付款按自己的编号 matched。
309		for i, w := range wantOrder {
310			r := rep.Results[i]
311			if r.Index != i || r.ID != w.id || r.Kind != w.kind {
312				t.Fatalf("result %d not in input order: %+v want %s/%s", i, r, w.kind, w.id)
313			}
314			if r.Status != w.status {
315				t.Fatalf("result %d (%s) status=%s want %s; swapped settlement_id must be reported even when totals net zero",
316					i, r.ID, r.Status, w.status)
317			}
318		}
319		// r1 账本真正指向 p1，流水误填 p2；r2 反之。差异值逐字并列。
320		if got := regDiffMap(rep.Results[0])["settlement_id"]; got != [2]string{"p1", "p2"} {
321			t.Fatalf("r1 settlement_id diff=%v want ledger p1 flow p2", got)
322		}
323		if len(regDiffMap(rep.Results[0])) != 1 {
324			t.Fatalf("r1 must differ only on settlement_id: %+v", rep.Results[0].Diffs)
325		}
326		if got := regDiffMap(rep.Results[2])["settlement_id"]; got != [2]string{"p2", "p1"} {
327			t.Fatalf("r2 settlement_id diff=%v want ledger p2 flow p1", got)
328		}
329		if len(regDiffMap(rep.Results[2])) != 1 {
330			t.Fatalf("r2 must differ only on settlement_id: %+v", rep.Results[2].Diffs)
331		}
332		// 记录详情携带账本中真正的原付款关联（以及退款自身序号），不能互相替代。
333		rec1 := rep.Results[0].Record
334		if rec1 == nil || rec1.Kind != "refund" || rec1.ID != "r1" || rec1.Seq != 1 ||
335			rec1.SettlementID != "p1" || rec1.Amount != 1000 || rec1.Fee != 3 || rec1.Charged != 1003 {
336			t.Fatalf("r1 record must carry true origin payment p1: %+v", rec1)
337		}
338		rec2 := rep.Results[2].Record
339		if rec2 == nil || rec2.Kind != "refund" || rec2.ID != "r2" || rec2.Seq != 2 ||
340			rec2.SettlementID != "p2" {
341			t.Fatalf("r2 record must carry true origin payment p2: %+v", rec2)
342		}
343		// 匹配的付款仍带各自退款关联，不因退款串号而丢失。
344		if rep.Results[1].Record == nil || rep.Results[1].Record.RefundID != "r1" {
345			t.Fatalf("p1 must still link refund r1: %+v", rep.Results[1].Record)
346		}
347		if rep.Results[3].Record == nil || rep.Results[3].Record.RefundID != "r2" {
348			t.Fatalf("p2 must still link refund r2: %+v", rep.Results[3].Record)
349		}
350	
351		// 四条记录全部通过各自编号找到：缺失列表（付款与退款）必须为空。
352		if len(rep.MissingRefunds) != 0 {
353			t.Fatalf("matched-by-id refunds must not be missing: %+v", rep.MissingRefunds)
354		}
355		if len(rep.MissingPayments) != 0 {
356			t.Fatalf("covered payments must not be missing: %+v", rep.MissingPayments)
357		}
358	
359		// 两侧扣款合计 2006、退款合计 2006、净扣款为零、净差额为十进制零。
360		regAssertBalancedTotals(t, rep, "2006", "2006")
361	
362		// 交换回正确的原付款编号后四条全部恢复 matched；金额字段本就一致。
363		corrected := []FlowEntry{
364			{Index: 0, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
365				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
366			{Index: 1, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
367			{Index: 2, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
368				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
369			{Index: 3, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
370		}
371		rep2, err := l.ReconcileFlow(corrected)
372		if err != nil {
373			t.Fatalf("reconcile corrected: %v", err)
374		}
375		for i, r := range rep2.Results {
376			if r.Status != ReconMatched || len(r.Diffs) != 0 {
377				t.Fatalf("corrected result %d (%s)=%+v want matched", i, r.ID, r)
378			}
379		}
380		if len(rep2.MissingPayments) != 0 || len(rep2.MissingRefunds) != 0 {
381			t.Fatalf("corrected missing=%+v/%+v", rep2.MissingPayments, rep2.MissingRefunds)
382		}
383		regAssertBalancedTotals(t, rep2, "2006", "2006")
384	}
385	
386	// TestReconcileRefundedPaymentStillCheckedOnItsOwn 付款曾经退款不影响原付款的
387	// 核对：同一批流水里一笔退款 settlement_id 串号，另一笔原付款按自己的编号与
388	// 金额判断；两类记录各按自己的编号空间匹配，不能因为金额相同就互相替代。
389	func TestReconcileRefundedPaymentStillCheckedOnItsOwn(t *testing.T) {
390		l, _ := regNetZeroLedger(t)
391		// r1 编号命中、金额正确，但原付款误填成 p2 -> field_mismatch(settlement_id)；
392		// p1 按原扣款如实呈现 -> matched。两笔金额相同（1003）不允许互相顶替。
393		entries := []FlowEntry{
394			{Index: 0, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
395				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
396			{Index: 1, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc",
397				Amount: 1000, Fee: 3, Charged: 1003},
398		}
399		rep, err := l.ReconcileFlow(entries)
400		if err != nil {
401			t.Fatalf("reconcile: %v", err)
402		}
403		if rep.Results[0].Status != ReconFieldMismatch {
404			t.Fatalf("r1=%s want field_mismatch", rep.Results[0].Status)
405		}
406		if d := regDiffMap(rep.Results[0]); len(d) != 1 || d["settlement_id"] != [2]string{"p1", "p2"} {
407			t.Fatalf("r1 diffs=%v", d)
408		}
409		if rep.Results[1].Status != ReconMatched {
410			t.Fatalf("p1=%s want matched even though it was refunded and r1 mismatches", rep.Results[1].Status)
411		}
412		// 已退款的付款匹配时仍带退款关联；退款记录带真正的原付款编号。
413		if rep.Results[1].Record == nil || rep.Results[1].Record.RefundID != "r1" {
414			t.Fatalf("p1 must still link refund r1: %+v", rep.Results[1].Record)
415		}
416		if rep.Results[0].Record == nil || rep.Results[0].Record.SettlementID != "p1" {
417			t.Fatalf("r1 record must carry true settlement p1: %+v", rep.Results[0].Record)
418		}
419		// p1、r1 均已覆盖；缺失只剩 p2、r2。
420		if ids := refs(rep.MissingPayments); ids != "p2" {
421			t.Fatalf("missing payments=%s want p2", ids)
422		}
423		if ids := refs(rep.MissingRefunds); ids != "r2" {
424			t.Fatalf("missing refunds=%s want r2", ids)
425		}
426	}
427	
428	// TestReconcileNetZeroDeviationsAndRecoveryAcrossSameBatch 同一批流水先呈现
429	// 跨记录偏差（净额对平），再把偏差全部改回账本原值：偏差状态、缺失列表、
430	// 汇总金额与恢复后的 matched 必须在同一份公开报告结构里自洽表达同一批流水。
431	func TestReconcileNetZeroDeviationsAndRecoveryAcrossSameBatch(t *testing.T) {
432		l, _ := regNetZeroLedger(t)
433	
434		// 混合一批：p1 多记 20、p2 少记 20（付款净额对平）；r1 串号到 p2
435		// （退款净额因 r2 缺席不再对平，但 r1 自身仍是 settlement_id 不符）。
436		bad := []FlowEntry{
437			{Index: 0, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 980, Fee: 3, Charged: 983},
438			{Index: 1, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
439				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
440			{Index: 2, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1020, Fee: 3, Charged: 1023},
441		}
442		rep, err := l.ReconcileFlow(bad)
443		if err != nil {
444			t.Fatalf("reconcile: %v", err)
445		}
446		wantStatus := []string{ReconFieldMismatch, ReconFieldMismatch, ReconFieldMismatch}
447		for i, r := range rep.Results {
448			if r.Status != wantStatus[i] {
449				t.Fatalf("bad batch result %d (%s)=%s want %s", i, r.ID, r.Status, wantStatus[i])
450			}
451		}
452		// 输入顺序同时保留（付款与退款交错，不重排）。
453		wantOrder := []string{"p2", "r1", "p1"}
454		for i, r := range rep.Results {
455			if r.ID != wantOrder[i] || r.Index != i {
456				t.Fatalf("result %d id=%s index=%d want %s", i, r.ID, r.Index, wantOrder[i])
457			}
458		}
459		if len(rep.MissingPayments) != 0 {
460			t.Fatalf("bad batch missing payments=%+v", rep.MissingPayments)
461		}
462		if ids := refs(rep.MissingRefunds); ids != "r2" {
463			t.Fatalf("bad batch missing refunds=%s want r2", ids)
464		}
465		// 付款扣款合计仍为 2006（983+1023），但流水只来一笔退款 1003：
466		// 净扣款 = 1003，而账本净扣款为 0，净差额 +1003——逐项偏差与汇总并存。
467		fl := regRow(t, rep.Totals.Flow, "aa-1", "usdc")
468		if fl.ChargedTotal != "2006" || fl.RefundedTotal != "1003" || fl.NetCharged != "1003" {
469			t.Fatalf("flow totals=%+v", fl)
470		}
471		if d := regDiff(t, rep, "aa-1", "usdc"); d.NetChargedDiff != "1003" {
472			t.Fatalf("net diff=%+v want 1003", d)
473		}
474	
475		// 全部偏差改回账本原值（r1 指回 p1），并补齐 r2 与正确的 p1/p2：
476		// 四条全部 matched，两侧合计 2006/2006、净差额恢复为零。
477		good := []FlowEntry{
478			{Index: 0, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
479			{Index: 1, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
480				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
481			{Index: 2, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
482			{Index: 3, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
483				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
484		}
485		rep2, err := l.ReconcileFlow(good)
486		if err != nil {
487			t.Fatalf("reconcile good: %v", err)
488		}
489		for i, r := range rep2.Results {
490			if r.Status != ReconMatched {
491				t.Fatalf("good batch result %d (%s)=%s want matched", i, r.ID, r.Status)
492			}
493		}
494		if len(rep2.MissingPayments) != 0 || len(rep2.MissingRefunds) != 0 {
495			t.Fatalf("good batch missing=%+v/%+v", rep2.MissingPayments, rep2.MissingRefunds)
496		}
497		regAssertBalancedTotals(t, rep2, "2006", "2006")
498	}
499	
500	// TestReconcileNetZeroDeviationsAreValidReportsNotErrors 这些场景的输入字段与
501	// 数值全部合法：跨记录偏差必须作为正常对账报告返回（退出语义层面无错误），
502	// 不能变成 invalid_parameter，也不能省略不一致的逐条结果。
503	func TestReconcileNetZeroDeviationsAreValidReportsNotErrors(t *testing.T) {
504		l, _ := regNetZeroLedger(t)
505	
506		cases := []struct {
507			name    string
508			raw     string
509			badID   string // 必然带字段差异的编号
510			diffFld string
511		}{
512			{
513				"offsetting payment amounts",
514				`{"entries":[
515				 {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1020,"fee":3,"charged":1023},
516				 {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":980,"fee":3,"charged":983}
517				]}`,
518				"p1", "amount",
519			},
520			{
521				"swapped refund settlements",
522				`{"entries":[
523				 {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"},
524				 {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"}
525				]}`,
526				"r1", "settlement_id",
527			},
528			{
529				"amount/fee breakdown shift with equal charged",
530				`{"entries":[
531				 {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":990,"fee":13,"charged":1003}
532				]}`,
533				"p1", "amount",
534			},
535		}
536		for _, c := range cases {
537			entries, err := ParseReconcileRequest([]byte(c.raw))
538			if err != nil {
539				t.Fatalf("%s: valid input must parse: %v", c.name, err)
540			}
541			rep, err := l.ReconcileFlow(entries)
542			if err != nil || rep == nil {
543				t.Fatalf("%s: deviations are a normal report, not invalid_parameter: rep=%+v err=%v", c.name, rep, err)
544			}
545			found := false
546			for _, r := range rep.Results {
547				if r.ID != c.badID {
548					continue
549				}
550				found = true
551				if r.Status != ReconFieldMismatch {
552					t.Fatalf("%s: %s status=%s want field_mismatch", c.name, r.ID, r.Status)
553				}
554				if _, ok := regDiffMap(r)[c.diffFld]; !ok {
555					t.Fatalf("%s: %s missing diff on %s: %+v", c.name, r.ID, c.diffFld, r.Diffs)
556				}
557			}
558			if !found {
559				t.Fatalf("%s: inconsistent result for %s must not be omitted: %+v", c.name, c.badID, rep.Results)
560			}
561		}
562	}
563	
564	// TestReconcileNetZeroDeviationsAreReadOnly 带跨记录偏差的对账前后，余额、
565	// 付款与退款历史以及账本文件内容必须逐字节保持一致（偏差只存在于报告中）。
566	func TestReconcileNetZeroDeviationsAreReadOnly(t *testing.T) {
567		l, path := regNetZeroLedger(t)
568	
569		before, err := l.Query()
570		if err != nil {
571			t.Fatalf("query before: %v", err)
572		}
573		bj, err := json.Marshal(before)
574		if err != nil {
575			t.Fatalf("marshal before: %v", err)
576		}
577		diskBefore, err := os.ReadFile(path)
578		if err != nil {
579			t.Fatalf("read ledger before: %v", err)
580		}
581	
582		deviating := []FlowEntry{
583			{Index: 0, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1020, Fee: 3, Charged: 1023},
584			{Index: 1, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 980, Fee: 3, Charged: 983},
585			{Index: 2, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
586				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
587			{Index: 3, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
588				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
589		}
590		rep, err := l.ReconcileFlow(deviating)
591		if err != nil {
592			t.Fatalf("reconcile: %v", err)
593		}
594		for i, r := range rep.Results {
595			if r.Status != ReconFieldMismatch {
596				t.Fatalf("setup: result %d (%s)=%s want field_mismatch", i, r.ID, r.Status)
597			}
598		}
599	
600		after, err := l.Query()
601		if err != nil {
602			t.Fatalf("query after: %v", err)
603		}
604		aj, err := json.Marshal(after)
605		if err != nil {
606			t.Fatalf("marshal after: %v", err)
607		}
608		if !reflect.DeepEqual(before, after) {
609			t.Fatalf("ledger state changed by reconcile:\nbefore=%s\nafter =%s", bj, aj)
610		}
611		diskAfter, err := os.ReadFile(path)
612		if err != nil {
613			t.Fatalf("read ledger after: %v", err)
614		}
615		if string(diskBefore) != string(diskAfter) {
616			t.Fatalf("ledger file changed by reconcile:\nbefore=%s\nafter =%s", diskBefore, diskAfter)
617		}
618	
619		// 重新打开同一文件，余额与成功历史仍与对账前完全一致。
620		l2, err := Open(path)
621		if err != nil {
622			t.Fatalf("reopen: %v", err)
623		}
624		defer l2.Close()
625		reopened, err := l2.Query()
626		if err != nil {
627			t.Fatalf("query reopened: %v", err)
628		}
629		if !reflect.DeepEqual(before, reopened) {
630			rj, _ := json.Marshal(reopened)
631			t.Fatalf("reopened ledger differs:\ndisk=%s\nmem =%s", rj, bj)
632		}
633	}
