368	func decodeState(data []byte) (*ledgerState, error) {
369		var state ledgerState
370		if err := json.Unmarshal(data, &state); err != nil {
371			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
372				return nil, err
373			}
374			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
375		}
376		return &state, nil
377	}
