1	package main
2	
3	import (
4		"encoding/json"
5		"os"
6		"testing"
7	
8		"github.com/gzhysuiioo/payflow-settlement/payflow"
9	)
10	
11	// 本文件从公开命令行入口（payflow reconcile，全量对账）回归保障：
12	// 净扣款差额为零时，报告仍逐笔保留跨记录偏差。
13	//
14	// 账本：aa-1/usdc 下两笔等额成功付款 p1、p2（amount=1000 fee=3 charged=1003，
15	// 30bps），分别被 r1（退 p1）、r2（退 p2）全额退款。外部流水在两种构造下
16	// 总额都与账本完全对平：
17	//   - p1 多记 20、p2 等额少记 20（编号、账户、资产、fee 正确）；
18	//   - r1、r2 交换各自引用的原付款编号（其余字段全部正确）。
19	//
20	// 报告必须逐笔给出 field_mismatch 与每个差异字段的账本值/流水值，记录详情
21	// 指向各自原记录，命中编号的记录不进缺失列表，逐条结果保持输入顺序，同时
22	// totals/net_diff 如实反映总额相等（net_charged_diff 为十进制 "0"）。偏差改回
23	// 账本原值后全部恢复 matched。整个过程对账退出码为 0（差异是正常报告，不是
24	// invalid_parameter），且 query 输出与账本文件内容逐字节不变。
25	
26	// cliNetZeroLedger 用命令行入口准备两笔付款与两笔退款，返回账本路径。
27	func cliNetZeroLedger(t *testing.T) string {
28		t.Helper()
29		ledgerPath := t.TempDir() + "/ledger.json"
30		if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
31			`{"balances":[{"account":"aa-1","asset":"usdc","balance":100000000}]}`); r.code != 0 {
32			t.Fatalf("init: %s", r.err)
33		}
34		if r := runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":30,"intents":[
35		  {"id":"p1","account":"aa-1","paymaster":"pm","asset":"usdc","amount":1000,"nonce":1},
36		  {"id":"p2","account":"aa-1","paymaster":"pm","asset":"usdc","amount":1000,"nonce":2}
37		]}`); r.code != 0 {
38			t.Fatalf("submit: %s", r.err)
39		}
40		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, `{"refunds":[
41		  {"id":"r1","settlement_id":"p1","reason":"cancel"},
42		  {"id":"r2","settlement_id":"p2","reason":"cancel"}
43		]}`); r.code != 0 {
44			t.Fatalf("refund: %s", r.err)
45		}
46		return ledgerPath
47	}
48	
49	// cliRecon 走全量对账入口，差异必须是退出码 0 的正常报告而非错误信封。
50	func cliRecon(t *testing.T, ledgerPath, body string) payflow.ReconReport {
51		t.Helper()
52		r := runCLIWith(t, []string{"reconcile", "-l", ledgerPath}, body)
53		if r.code != 0 {
54			t.Fatalf("reconcile must exit 0 with valid-but-diverging flow, got code=%d stderr=%s", r.code, r.err)
55		}
56		if r.err != "" {
57			t.Fatalf("reconcile must not emit an error envelope: %s", r.err)
58		}
59		var rep payflow.ReconReport
60		if err := json.Unmarshal([]byte(r.out), &rep); err != nil {
61			t.Fatalf("decode report: %v\n%s", err, r.out)
62		}
63		return rep
64	}
65	
66	func cliReconResult(rep payflow.ReconReport, id string) payflow.ReconResult {
67		for _, r := range rep.Results {
68			if r.ID == id {
69				return r
70			}
71		}
72		return payflow.ReconResult{}
73	}
74	
75	func cliTotalRow(t *testing.T, rows []payflow.ReconTotalRow) payflow.ReconTotalRow {
76		t.Helper()
77		for _, r := range rows {
78			if r.Account == "aa-1" && r.Asset == "usdc" {
79				return r
80			}
81		}
82		t.Fatalf("aa-1/usdc total row missing: %+v", rows)
83		return payflow.ReconTotalRow{}
84	}
85	
86	// cliAssertNetZero 汇总两侧都是 charged/refunded 给定值、净扣款 0、净差额 "0"。
87	func cliAssertNetZero(t *testing.T, rep payflow.ReconReport, chargedTotal, refundedTotal string) {
88		t.Helper()
89		lg := cliTotalRow(t, rep.Totals.Ledger)
90		fl := cliTotalRow(t, rep.Totals.Flow)
91		if lg.ChargedTotal != chargedTotal || lg.RefundedTotal != refundedTotal || lg.NetCharged != "0" {
92			t.Fatalf("ledger totals=%+v", lg)
93		}
94		if fl.ChargedTotal != chargedTotal || fl.RefundedTotal != refundedTotal || fl.NetCharged != "0" {
95			t.Fatalf("flow totals=%+v", fl)
96		}
97		if len(rep.NetDiff) != 1 {
98			t.Fatalf("net_diff=%+v want single row", rep.NetDiff)
99		}
100		d := rep.NetDiff[0]
101		if d.Account != "aa-1" || d.Asset != "usdc" ||
102			d.LedgerNetCharged != "0" || d.FlowNetCharged != "0" || d.NetChargedDiff != "0" {
103			t.Fatalf("net_diff=%+v want decimal zero", d)
104		}
105	}
106	
107	func cliDiffMap(r payflow.ReconResult) map[string][2]string {
108		out := make(map[string][2]string, len(r.Diffs))
109		for _, d := range r.Diffs {
110			out[d.Field] = [2]string{d.Ledger, d.Flow}
111		}
112		return out
113	}
114	
115	// TestCLIReconcileNetZeroKeepsPerRecordDiffs 净差额为零时逐笔差异仍完整保留：
116	// 付款一多一少对平、退款原付款编号互换、修复后恢复 matched，且全程只读。
117	func TestCLIReconcileNetZeroKeepsPerRecordDiffs(t *testing.T) {
118		ledgerPath := cliNetZeroLedger(t)
119	
120		// 对账前的公开查询结果与账本文件内容基线。
121		queryBefore := runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
122		if queryBefore.code != 0 {
123			t.Fatalf("query before: %s", queryBefore.err)
124		}
125		fileBefore, err := os.ReadFile(ledgerPath)
126		if err != nil {
127			t.Fatalf("read ledger before: %v", err)
128		}
129	
130		// ---- 场景一：p1 多记 20、p2 少记 20；两笔退款正确。交错输入。----
131		offsetBody := `{"entries":[
132		  {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":980,"fee":3,"charged":983},
133		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
134		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1020,"fee":3,"charged":1023},
135		  {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"}
136		]}`
137		rep := cliRecon(t, ledgerPath, offsetBody)
138	
139		// 逐条结果严格保持外部流水输入顺序。
140		want := []struct {
141			id     string
142			status string
143		}{
144			{"p2", payflow.ReconFieldMismatch},
145			{"r1", payflow.ReconMatched},
146			{"p1", payflow.ReconFieldMismatch},
147			{"r2", payflow.ReconMatched},
148		}
149		if len(rep.Results) != len(want) {
150			t.Fatalf("results=%d want %d", len(rep.Results), len(want))
151		}
152		for i, w := range want {
153			r := rep.Results[i]
154			if r.Index != i || r.ID != w.id || r.Status != w.status {
155				t.Fatalf("result %d=%+v want id=%s status=%s", i, r, w.id, w.status)
156			}
157		}
158		// 两笔付款分别带出实际不同字段的账本值与流水值（不多不少）。
159		d2 := cliDiffMap(cliReconResult(rep, "p2"))
160		if len(d2) != 2 || d2["amount"] != [2]string{"1000", "980"} || d2["charged"] != [2]string{"1003", "983"} {
161			t.Fatalf("p2 diffs=%v", d2)
162		}
163		d1 := cliDiffMap(cliReconResult(rep, "p1"))
164		if len(d1) != 2 || d1["amount"] != [2]string{"1000", "1020"} || d1["charged"] != [2]string{"1003", "1023"} {
165			t.Fatalf("p1 diffs=%v", d1)
166		}
167		// 记录详情仍指向各自原付款（含各自退款关联）。
168		p2 := cliReconResult(rep, "p2").Record
169		if p2 == nil || p2.ID != "p2" || p2.Seq != 2 || p2.Amount != 1000 || p2.Charged != 1003 || p2.RefundID != "r2" {
170			t.Fatalf("p2 record=%+v", p2)
171		}
172		p1 := cliReconResult(rep, "p1").Record
173		if p1 == nil || p1.ID != "p1" || p1.Seq != 1 || p1.RefundID != "r1" {
174			t.Fatalf("p1 record=%+v", p1)
175		}
176		// 已通过编号找到的四笔不能出现在缺失列表。
177		if len(rep.MissingPayments) != 0 || len(rep.MissingRefunds) != 0 {
178			t.Fatalf("missing payments=%+v refunds=%+v", rep.MissingPayments, rep.MissingRefunds)
179		}
180		// 扣款 983+1023=2006、退款 2006：净差额为十进制零，但逐笔差异保留。
181		cliAssertNetZero(t, rep, "2006", "2006")
182	
183		// 偏差改回账本原值：四条全部 matched，汇总仍正确。
184		fixedBody := `{"entries":[
185		  {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
186		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
187		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
188		  {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"}
189		]}`
190		rep = cliRecon(t, ledgerPath, fixedBody)
191		for i, r := range rep.Results {
192			if r.Status != payflow.ReconMatched {
193				t.Fatalf("fixed result %d (%s)=%s want matched", i, r.ID, r.Status)
194			}
195		}
196		if len(rep.MissingPayments) != 0 || len(rep.MissingRefunds) != 0 {
197			t.Fatalf("fixed missing=%+v/%+v", rep.MissingPayments, rep.MissingRefunds)
198		}
199		cliAssertNetZero(t, rep, "2006", "2006")
200	
201		// ---- 场景二：两笔退款交换原付款编号；两笔付款正确。交错输入。----
202		swapBody := `{"entries":[
203		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"},
204		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
205		  {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
206		  {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003}
207		]}`
208		rep = cliRecon(t, ledgerPath, swapBody)
209		wantOrder := []struct {
210			id     string
211			status string
212		}{
213			{"r1", payflow.ReconFieldMismatch},
214			{"p1", payflow.ReconMatched},
215			{"r2", payflow.ReconFieldMismatch},
216			{"p2", payflow.ReconMatched},
217		}
218		for i, w := range wantOrder {
219			r := rep.Results[i]
220			if r.Index != i || r.ID != w.id || r.Status != w.status {
221				t.Fatalf("swap result %d=%+v want id=%s status=%s", i, r, w.id, w.status)
222			}
223		}
224		// 差异明确落在 settlement_id，并携带账本中真正的原付款关联。
225		sd1 := cliDiffMap(cliReconResult(rep, "r1"))
226		if len(sd1) != 1 || sd1["settlement_id"] != [2]string{"p1", "p2"} {
227			t.Fatalf("r1 diffs=%v", sd1)
228		}
229		sd2 := cliDiffMap(cliReconResult(rep, "r2"))
230		if len(sd2) != 1 || sd2["settlement_id"] != [2]string{"p2", "p1"} {
231			t.Fatalf("r2 diffs=%v", sd2)
232		}
233		r1rec := cliReconResult(rep, "r1").Record
234		if r1rec == nil || r1rec.SettlementID != "p1" || r1rec.Seq != 1 {
235			t.Fatalf("r1 record=%+v must carry true origin p1", r1rec)
236		}
237		r2rec := cliReconResult(rep, "r2").Record
238		if r2rec == nil || r2rec.SettlementID != "p2" || r2rec.Seq != 2 {
239			t.Fatalf("r2 record=%+v must carry true origin p2", r2rec)
240		}
241		if len(rep.MissingPayments) != 0 || len(rep.MissingRefunds) != 0 {
242			t.Fatalf("swap missing=%+v/%+v", rep.MissingPayments, rep.MissingRefunds)
243		}
244		cliAssertNetZero(t, rep, "2006", "2006")
245	
246		// 编号换回来后全部 matched。
247		rep = cliRecon(t, ledgerPath, fixedBody)
248		for _, r := range rep.Results {
249			if r.Status != payflow.ReconMatched {
250				t.Fatalf("restored %s=%s want matched", r.ID, r.Status)
251			}
252		}
253	
254		// ---- 金额/手续费分项不同但 charged 相同：分项差异仍保留。----
255		breakdownBody := `{"entries":[
256		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":990,"fee":13,"charged":1003}
257		]}`
258		rep = cliRecon(t, ledgerPath, breakdownBody)
259		bd := cliDiffMap(rep.Results[0])
260		if rep.Results[0].Status != payflow.ReconFieldMismatch ||
261			len(bd) != 2 || bd["amount"] != [2]string{"1000", "990"} || bd["fee"] != [2]string{"3", "13"} {
262			t.Fatalf("breakdown result=%+v diffs=%v", rep.Results[0], bd)
263		}
264	
265		// ---- 全程只读：query 输出与账本文件逐字节一致。----
266		queryAfter := runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
267		if queryAfter.code != 0 {
268			t.Fatalf("query after: %s", queryAfter.err)
269		}
270		if queryBefore.out != queryAfter.out {
271			t.Fatalf("ledger changed by reconcile:\nbefore=%s\nafter =%s", queryBefore.out, queryAfter.out)
272		}
273		fileAfter, err := os.ReadFile(ledgerPath)
274		if err != nil {
275			t.Fatalf("read ledger after: %v", err)
276		}
277		if string(fileBefore) != string(fileAfter) {
278			t.Fatalf("ledger file changed by reconcile:\nbefore=%s\nafter =%s", fileBefore, fileAfter)
279		}
280	}
